  VALUES (uuid_generate_v4(), 'randtest.tyler.scott.17900@test.com', 'player', true, true, true, 'randtest-' || gen_random_uuid()::text, 'tylerscott4715', 'none', NULL, NULL, NULL)
  RETURNING id
),
new_profile AS (
  INSERT INTO player_profiles (user_id, first_name, last_name, date_of_birth, team_name, graduation_year, city, state, height, weight, gpa, sat_score, act_score, bio, phone, hudl_profile, twitter_handle, instagram_handle, player_status, username, cc_views, college_division, transfer, eligibility, number, conference, offers, star_rating, followers_count, following_count, message_permissions, profile_visibility, position, lastseasonstat1, lastseasonstat2, lastseasonstat3, careerstat1, careerstat2, careerstat3, pff_grade)
  SELECT nu.id, 'Tyler', 'Scott', DATE '2007-12-29', 'Eastern Michigan University', 2026, 'Knoxville', 'Tennessee', 73, 236, 2.73, NULL, NULL, 'Transferring to find the right fit. Years of eligibility left to make an impact.', '555-546-3386', 'https://hudl.com/profile/tylerscott4715', '@tylerscott4715', '@tylerscott4715', 'junior', 'tylerscott4715', 292, 'D1 FBS', 'y', 1, 81, 'SEC', 'Trine University, D3|Framingham State University, D3|Bridgewater College, D3|Post University, D2|Centenary College of Louisiana, D3|Howard University, D1 FCS|Linfield University, D3|Lafayette College, D1 FCS', NULL, 580, 167, 'followers', 'everyone', 'ILB', 82, 11, 4, 163, 21, 8, 48.7
  FROM new_user nu RETURNING id, user_id
),
g_career AS (INSERT INTO player_games (player_id, game_date, season_year, opponent, result) SELECT id, CURRENT_DATE, 0, NULL, NULL FROM new_profile RETURNING id, player_id),
g_last AS (INSERT INTO player_games (player_id, game_date, season_year, opponent, result) SELECT id, CURRENT_DATE, -1, NULL, NULL FROM new_profile RETURNING id, player_id),
hl1 AS (INSERT INTO player_highlights (user_id, highlight_type, title, hudl_link, video_url) SELECT user_id, 'sophomore', 'Sophomore Season Highlights', 'https://hudl.com/v/tylerscott4715/sophomore', NULL FROM new_profile RETURNING id),
hl2 AS (INSERT INTO player_highlights (user_id, highlight_type, title, hudl_link, video_url) SELECT user_id, 'junior', 'Junior Season Highlights', 'https://hudl.com/v/tylerscott4715/junior', NULL FROM new_profile RETURNING id),
stat_career AS (INSERT INTO player_game_stats (game_id, position, stats, player_name, user_id) SELECT g_career.id, 'ILB', jsonb_build_object('tackles', 163, 'tfls', 21, 'sacks', 8, 'ff', 3, 'int', 4, 'pbu', 14), 'Tyler Scott', np.user_id FROM g_career, new_profile np RETURNING id)
INSERT INTO player_game_stats (game_id, position, stats, player_name, user_id) SELECT g_last.id, 'ILB', jsonb_build_object('tackles', 82, 'tfls', 11, 'sacks', 4, 'ff', 2, 'int', 2, 'pbu', 7), 'Tyler Scott', np.user_id FROM g_last, new_profile np;
COMMIT;

